//! `cbor/test-vectors` `appendix_a.json`: the examples of RFC 8949 Appendix A
//! (the same set as RFC 7049's), as a table of (encoded bytes, expected
//! tokens or rejection) for `clazel-ipc`'s profile.
//!
//! Each element has `hex`, `roundtrip`, and either `decoded` (a JSON value)
//! or `diagnostic` (CBOR diagnostic notation). A vector is **inside the
//! profile** when all of these hold, judged only from the JSON, never from
//! our decoder:
//! - `roundtrip` is true (indefinite lengths are the `false` ones);
//! - it has `decoded` and that value is built from unsigned integers that
//!   JSON stores as integers, strings, booleans and arrays of those, or it
//!   has a `diagnostic` of the form `h'...'` (a byte string);
//! - the first byte is not a tag (major type 6).
//!
//! Inside the profile the expected tokens are computed from the JSON value;
//! every other vector must be rejected.

use std::fmt::Write as _;
use std::path::Path;

use serde_json::Value;

/// The files vendored for this suite (besides LICENSE.md and SOURCE.md).
pub const FILES: &[&str] = &["appendix_a.json"];

enum Tok {
    Uint(u64),
    Bytes(Vec<u8>),
    Text(Vec<u8>),
    Bool(bool),
    Array(u64),
}

fn flatten(v: &Value, out: &mut Vec<Tok>) -> Option<()> {
    match v {
        Value::Bool(b) => out.push(Tok::Bool(*b)),
        Value::Number(n) => out.push(Tok::Uint(n.as_u64()?)),
        Value::String(s) => out.push(Tok::Text(s.as_bytes().to_vec())),
        Value::Array(items) => {
            out.push(Tok::Array(u64::try_from(items.len()).ok()?));
            for i in items {
                flatten(i, out)?;
            }
        }
        _ => return None,
    }
    Some(())
}

fn parse_hex(h: &str) -> Result<Vec<u8>, String> {
    if !h.len().is_multiple_of(2) {
        return Err(format!("odd hex length: {h}"));
    }
    (0..h.len())
        .step_by(2)
        .map(|i| {
            h.get(i..i.saturating_add(2))
                .and_then(|p| u8::from_str_radix(p, 16).ok())
                .ok_or_else(|| format!("bad hex: {h}"))
        })
        .collect()
}

fn bytes_literal(b: &[u8]) -> String {
    let v: Vec<String> = b.iter().map(|x| format!("0x{x:02X}")).collect();
    format!("&[{}]", v.join(", "))
}

pub fn convert(dir: &Path) -> Result<String, String> {
    let path = dir.join("appendix_a.json");
    let text = std::fs::read_to_string(&path).map_err(|e| format!("appendix_a.json: {e}"))?;
    let rows: Value = serde_json::from_str(&text).map_err(|e| format!("appendix_a.json: {e}"))?;
    let rows = rows.as_array().ok_or("appendix_a.json: not an array")?;
    let mut out = String::new();
    out.push_str("// @generated by `cargo xtask testdata` from tests/data/cbor-appendix-a/.\n");
    out.push_str("// Do not edit: `cargo xtask verify` fails if this differs from what the\n");
    out.push_str("// converter (xtask/src/testdata/cbor_appendix_a.rs) produces.\n");
    out.push_str("// Source, commit and license: tests/data/cbor-appendix-a/SOURCE.md.\n");
    out.push_str("const APPENDIX_A: &[Case] = &[\n");
    for (index, row) in rows.iter().enumerate() {
        let at = |e: String| format!("appendix_a.json[{index}]: {e}");
        let hex = row
            .get("hex")
            .and_then(Value::as_str)
            .ok_or_else(|| at("no hex".into()))?;
        let bytes = parse_hex(hex).map_err(&at)?;
        let roundtrip = row
            .get("roundtrip")
            .and_then(Value::as_bool)
            .ok_or_else(|| at("no roundtrip".into()))?;
        let major = bytes
            .first()
            .map(|b| b / 32)
            .ok_or_else(|| at("empty".into()))?;
        let mut toks = Vec::new();
        let inside = roundtrip
            && major != 6
            && if let Some(d) = row.get("decoded") {
                flatten(d, &mut toks).is_some()
            } else if let Some(diag) = row.get("diagnostic").and_then(Value::as_str) {
                match diag.strip_prefix("h'").and_then(|r| r.strip_suffix('\'')) {
                    Some(h) => {
                        toks.push(Tok::Bytes(parse_hex(h).map_err(&at)?));
                        true
                    }
                    None => false,
                }
            } else {
                false
            };
        let expected = if inside {
            let items: Vec<String> = toks
                .iter()
                .map(|t| match t {
                    Tok::Uint(n) => format!("Exp::Uint({n})"),
                    Tok::Bytes(b) => format!("Exp::Bytes({})", bytes_literal(b)),
                    Tok::Text(b) => format!("Exp::Text({})", bytes_literal(b)),
                    Tok::Bool(b) => format!("Exp::Bool({b})"),
                    Tok::Array(n) => format!("Exp::Array({n})"),
                })
                .collect();
            format!("Some(&[{}])", items.join(", "))
        } else {
            "None".to_owned()
        };
        writeln!(
            out,
            "    Case {{ index: {index}, bytes: {}, expected: {expected} }},",
            bytes_literal(&bytes)
        )
        .map_err(|e| e.to_string())?;
    }
    out.push_str("];\n");
    Ok(out)
}
